"""codebench_mpl_viewer — turn a 2-D matplotlib Figure into a self-contained
interactive HTML page that BEATS the plotly shim:

  • EXACT matplotlib SVG  → true vector, infinitely crisp (sharper than plotly,
    which re-renders); mathtext, styles, every artist render pixel-faithfully.
  • smooth zoom / pan     → wheel + pinch to zoom, drag to pan (viewBox), double
    -tap / button to reset — direct manipulation, not a modal toolbar.
  • data-value hover      → the real (x, y) of the nearest data point in a
    tooltip + a highlight marker, on mouse-move AND touch (iPad).

`build_interactive_html(fig)` returns the HTML string for a 2-D figure, or
None for a 3-D figure (the caller falls back to the WebAgg rotate backend).
No server, no external assets — one file that renders anywhere.
"""
import io
import json
import re


def _looks_3d(fig):
    for ax in fig.axes:
        if getattr(ax, "name", "") == "3d":
            return True
    return False


def build_interactive_html(fig):
    if _looks_3d(fig):
        return None                      # 3-D → caller uses WebAgg (rotate)
    try:
        import numpy as np
    except Exception:
        np = None

    # 1) exact vector render ------------------------------------------------
    buf = io.StringIO()
    fig.savefig(buf, format="svg")
    svg = buf.getvalue()
    j = svg.find("<svg")
    if j > 0:
        svg = svg[j:]                    # drop <?xml…?> / <!DOCTYPE…> prologue

    # figure geometry: display px → SVG user units (points)
    dpi = float(fig.dpi)
    h_in = float(fig.get_size_inches()[1])
    Hpx = h_in * dpi
    k = 72.0 / dpi                       # 1 display px = k points in the SVG

    def d2svg(px, py):                   # mpl display (y-up) → SVG user (y-down)
        return [px * k, (Hpx - py) * k]

    # 2) pull real data out of every axes for hover -------------------------
    series = []

    def _add(label, xy_disp, xd, yd):
        pts = []
        for (px, py), dx, dy in zip(xy_disp, xd, yd):
            sx, sy = d2svg(px, py)
            pts.append([round(sx, 2), round(sy, 2), _num(dx), _num(dy)])
        if pts:
            series.append({"label": str(label), "pts": pts})

    def _num(v):
        try:
            f = float(v)
            return round(f, 6)
        except Exception:
            return None

    for ax in fig.axes:
        try:
            for ln in ax.get_lines():
                xd = list(ln.get_xdata()); yd = list(ln.get_ydata())
                if not xd:
                    continue
                pairs = list(zip(xd, yd))
                disp = ax.transData.transform(pairs) if np is None \
                    else ax.transData.transform(np.asarray(pairs, float))
                lbl = ln.get_label()
                if isinstance(lbl, str) and lbl.startswith("_"):
                    lbl = ""
                _add(lbl, disp, xd, yd)
            for col in ax.collections:            # scatter, etc.
                off = col.get_offsets()
                if off is None or len(off) == 0:
                    continue
                disp = ax.transData.transform(off)
                xd = [o[0] for o in off]; yd = [o[1] for o in off]
                lbl = getattr(col, "get_label", lambda: "")()
                if isinstance(lbl, str) and lbl.startswith("_"):
                    lbl = ""
                _add(lbl, disp, xd, yd)
        except Exception:
            continue                              # never let hover break render

    # 3) responsive <svg>: force width/height to 100% and capture viewBox ---
    m = re.search(r'viewBox="([^"]+)"', svg)
    if m:
        view_box = m.group(1)
    else:
        w_in = float(fig.get_size_inches()[0])
        view_box = f"0 0 {w_in * 72:.2f} {h_in * 72:.2f}"
        svg = svg.replace("<svg", f'<svg viewBox="{view_box}"', 1)
    # make the root svg fill the container and give it a hook id
    svg = re.sub(r'<svg([^>]*?)\swidth="[^"]*"', r"<svg\1", svg, count=1)
    svg = re.sub(r'<svg([^>]*?)\sheight="[^"]*"', r"<svg\1", svg, count=1)
    svg = svg.replace(
        "<svg",
        '<svg id="mplsvg" preserveAspectRatio="xMidYMid meet" '
        'style="width:100%;height:100%;display:block;touch-action:none"',
        1,
    )

    return _TEMPLATE.replace("/*__VIEWBOX__*/", json.dumps(view_box)) \
                    .replace("/*__DATA__*/", json.dumps(series)) \
                    .replace("<!--__SVG__-->", svg)


_TEMPLATE = r"""<!doctype html><html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no">
<style>
  html,body{margin:0;height:100%;background:#fff;overscroll-behavior:none;
    font:12px -apple-system,system-ui,sans-serif;color:#111}
  #wrap{position:fixed;inset:0;overflow:hidden;background:#fff}
  #stage{position:absolute;inset:0}
  #tip{position:fixed;pointer-events:none;background:rgba(17,17,17,.92);color:#fff;
    padding:5px 8px;border-radius:6px;font-size:12px;line-height:1.35;white-space:nowrap;
    transform:translate(-50%,calc(-100% - 12px));opacity:0;transition:opacity .08s;z-index:9;
    box-shadow:0 2px 8px rgba(0,0,0,.25)}
  #tip b{color:#6cf}
  #mk{position:absolute;width:11px;height:11px;margin:-6px 0 0 -6px;border:2px solid #d33;
    border-radius:50%;background:rgba(221,51,51,.25);opacity:0;pointer-events:none;z-index:8}
  #bar{position:fixed;left:10px;bottom:10px;display:flex;gap:6px;z-index:10}
  #bar button{all:unset;cursor:pointer;background:rgba(0,0,0,.06);border-radius:7px;
    padding:6px 9px;font-size:13px;color:#333}
  #bar button:active{background:rgba(0,0,0,.14)}
  #hint{position:fixed;right:10px;bottom:10px;color:#999;font-size:11px;z-index:10;user-select:none}
</style></head>
<body>
<div id="wrap"><div id="stage"><!--__SVG__--><div id="mk"></div></div></div>
<div id="tip"></div>
<div id="bar"><button id="rz">Reset view</button></div>
<div id="hint">scroll / pinch = zoom · drag = pan · hover = value</div>
<script>
(function(){
  var svg=document.getElementById('mplsvg'), stage=document.getElementById('stage'),
      tip=document.getElementById('tip'), mk=document.getElementById('mk');
  if(!svg) return;
  var VB0=/*__VIEWBOX__*/.split(/[ ,]+/).map(Number);   // [x,y,w,h]
  var vb={x:VB0[0],y:VB0[1],w:VB0[2],h:VB0[3]};
  var SERIES=/*__DATA__*/;
  function apply(){ svg.setAttribute('viewBox',vb.x+' '+vb.y+' '+vb.w+' '+vb.h); }
  apply();

  // client px -> svg user coords, honouring the current viewBox + letterboxing
  function toUser(cx,cy){
    var r=svg.getBoundingClientRect();
    var sc=Math.min(r.width/vb.w, r.height/vb.h);        // xMidYMid meet
    var offx=(r.width - vb.w*sc)/2, offy=(r.height - vb.h*sc)/2;
    return { x: vb.x + (cx - r.left - offx)/sc,
             y: vb.y + (cy - r.top  - offy)/sc, sc:sc, r:r, offx:offx, offy:offy };
  }
  function userToClient(ux,uy){
    var r=svg.getBoundingClientRect();
    var sc=Math.min(r.width/vb.w, r.height/vb.h);
    var offx=(r.width - vb.w*sc)/2, offy=(r.height - vb.h*sc)/2;
    return { x:r.left+offx+(ux-vb.x)*sc, y:r.top+offy+(uy-vb.y)*sc };
  }

  // ---- zoom (wheel) ----
  stage.addEventListener('wheel',function(e){
    e.preventDefault();
    var u=toUser(e.clientX,e.clientY);
    var f=Math.pow(1.0015, e.deltaY);                    // >1 zoom out
    f=Math.max(.2,Math.min(5,f));
    vb.x=u.x-(u.x-vb.x)*f; vb.y=u.y-(u.y-vb.y)*f; vb.w*=f; vb.h*=f;
    apply(); hideTip();
  },{passive:false});

  // ---- pan (drag) + pinch (2 pointers) ----
  var pts={}, panLast=null, pinch=null;
  stage.addEventListener('pointerdown',function(e){
    stage.setPointerCapture(e.pointerId); pts[e.pointerId]={x:e.clientX,y:e.clientY};
    var ids=Object.keys(pts);
    if(ids.length===1){ panLast={x:e.clientX,y:e.clientY}; }
    else if(ids.length===2){ pinch=startPinch(ids); panLast=null; }
  });
  stage.addEventListener('pointermove',function(e){
    if(pts[e.pointerId]) pts[e.pointerId]={x:e.clientX,y:e.clientY};
    var ids=Object.keys(pts);
    if(ids.length>=2 && pinch){ doPinch(ids); return; }
    if(panLast && pts[e.pointerId]){
      var r=svg.getBoundingClientRect(), sc=Math.min(r.width/vb.w,r.height/vb.h);
      vb.x-=(e.clientX-panLast.x)/sc; vb.y-=(e.clientY-panLast.y)/sc;
      panLast={x:e.clientX,y:e.clientY}; apply(); hideTip(); return;
    }
    hover(e.clientX,e.clientY);                            // no drag → hover
  });
  function up(e){ delete pts[e.pointerId];
    var ids=Object.keys(pts);
    if(ids.length<2) pinch=null;
    if(ids.length===0) panLast=null;
    else if(ids.length===1) panLast={x:pts[ids[0]].x,y:pts[ids[0]].y};
  }
  stage.addEventListener('pointerup',up); stage.addEventListener('pointercancel',up);
  stage.addEventListener('pointerleave',function(){ hideTip(); });

  function startPinch(ids){
    var a=pts[ids[0]],b=pts[ids[1]];
    var mx=(a.x+b.x)/2,my=(a.y+b.y)/2, d=Math.hypot(a.x-b.x,a.y-b.y);
    return {d:d, u:toUser(mx,my)};
  }
  function doPinch(ids){
    var a=pts[ids[0]],b=pts[ids[1]];
    var mx=(a.x+b.x)/2,my=(a.y+b.y)/2, d=Math.hypot(a.x-b.x,a.y-b.y);
    if(!pinch||!pinch.d){ pinch=startPinch(ids); return; }
    var f=pinch.d/Math.max(1,d); f=Math.max(.5,Math.min(2,f));
    var u=toUser(mx,my);
    vb.x=u.x-(u.x-vb.x)*f; vb.y=u.y-(u.y-vb.y)*f; vb.w*=f; vb.h*=f;
    pinch.d=d; apply(); hideTip();
  }

  // ---- hover: nearest data point across all series ----
  function hover(cx,cy){
    if(!SERIES.length){ return; }
    var u=toUser(cx,cy);
    var best=null,bd=1e18;
    for(var s=0;s<SERIES.length;s++){ var P=SERIES[s].pts;
      for(var i=0;i<P.length;i++){
        var dx=P[i][0]-u.x, dy=P[i][1]-u.y, dd=dx*dx+dy*dy;
        if(dd<bd){ bd=dd; best={s:s,i:i}; }
      }
    }
    if(!best){ hideTip(); return; }
    // only snap if the cursor is reasonably close (in user units)
    var r=svg.getBoundingClientRect(), sc=Math.min(r.width/vb.w,r.height/vb.h);
    if(Math.sqrt(bd)*sc>40){ hideTip(); return; }
    var P=SERIES[best.s].pts[best.i], lbl=SERIES[best.s].label;
    var cp=userToClient(P[0],P[1]);
    mk.style.left=(cp.x-r.left+stage.offsetLeft)+'px'; // stage is inset:0 → offset 0
    mk.style.left=(cp.x)+'px'; mk.style.top=(cp.y)+'px'; mk.style.opacity=1;
    tip.innerHTML=(lbl?('<b>'+esc(lbl)+'</b><br>'):'')+
      'x = '+fmt(P[2])+'<br>y = '+fmt(P[3]);
    tip.style.left=cp.x+'px'; tip.style.top=cp.y+'px'; tip.style.opacity=1;
  }
  function hideTip(){ tip.style.opacity=0; mk.style.opacity=0; }
  function fmt(v){ if(v===null||v===undefined) return '—';
    var a=Math.abs(v); return (a!==0&&(a<1e-3||a>=1e5))?v.toExponential(3):(''+(Math.round(v*1e6)/1e6)); }
  function esc(s){ return (''+s).replace(/[&<>]/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;'}[c];}); }

  document.getElementById('rz').onclick=function(){ vb={x:VB0[0],y:VB0[1],w:VB0[2],h:VB0[3]}; apply(); hideTip(); };
  window.addEventListener('dblclick',function(){ vb={x:VB0[0],y:VB0[1],w:VB0[2],h:VB0[3]}; apply(); hideTip(); });
})();
</script></body></html>"""
